import numpy as np

def design(x,t,kap,K):
    k=np.arange(1,K+1)
    return np.exp(-kap*np.pi**2*t[:,None]*k[None,:]**2)*np.sin(np.pi*x[:,None]*k[None,:])

# prior scale envelope (per-mode sd), informed by dev ensemble, mildly inflated
def prior_sd(K):
    base=np.array([1.5,0.45,0.12,0.10,0.14,0.08,0.08,0.06,0.05,0.04,0.035,0.03])
    s=np.empty(K)
    for k in range(K):
        if k<len(base): s[k]=base[k]
        else: s[k]=0.03
    return s

def map_gauss(A,y,sig,c):
    H=A.T@A/sig**2+np.diag(1.0/c)
    return np.linalg.solve(H,A.T@y/sig**2)

def map_t(A,y,sig,s,nu=2.0,niter=30):
    n,K=A.shape
    AtA=A.T@A/sig**2; Aty=A.T@y/sig**2
    c=s**2
    b=map_gauss(A,y,sig,c)
    lam=1.0/c
    for it in range(niter):
        bnew=np.linalg.solve(AtA+np.diag(lam),Aty)
        lam_new=(nu+1.0)/(nu*c+bnew**2) if False else (nu+1.0)/(nu*s**2+bnew**2)
        if np.max(np.abs(lam_new-lam))<1e-10*np.max(lam_new): lam=lam_new; b=bnew; break
        lam=lam_new; b=bnew
    return b

def estimate(x,t,y,kap,sig,K=32,kind='t',nu=2.0,sc=1.0):
    A=design(x,t,kap,K)
    s=prior_sd(K)*sc
    if kind=='t': return map_t(A,y,sig,s,nu)
    return map_gauss(A,y,sig,s**2)

def forward(b,kap,t,x):
    k=np.arange(1,len(b)+1)
    return (np.sin(np.pi*x[:,None]*k[None,:])*np.exp(-kap*np.pi**2*t*k**2)[None,:])@b
def relerr(a,b): return np.linalg.norm(a-b)/max(np.linalg.norm(b),1e-12)
