    # logdet(sig2 I_m + A diag(v) A^T) = (m-K)log sig2 + logdet(I_K + diag(v)^.5 C diag(v)^.5 /sig2)
    vv=np.sqrt(v); M=np.eye(K)+ (vv[:,None]*C*vv[None,:])/sig**2
    sign,ld=np.linalg.slogdet(M)
    logdet=(len(y)-K)*np.log(sig**2)+ld
