 ss=np.sum(w*(b-A@c)**2)
 return ne*np.log(ss/ne)+len(sup)*np.log(ne),ss,c

def local_search(A,b,w,sup,ne):
 sup=set(sup); best=BIC(A,b,w,sorted(sup),ne)[0]
