  for t in list(sup):
   cands.append(tuple(sorted(sup-{t})))
  for t in list(sup):
   for u in range(A.shape[1]):
    if u not in sup: cands.append(tuple(sorted((sup-{t})|{u})))
  for cnd in cands:
